$ ccm node1 cqlsh -e "INSERT INTO test.text_set_set (id, value1, value2, value3) values ('aaa', 'aaa', {'aaa', 'bbb'}, {'ccc', 'ddd'});"
$ ccm node1 cqlsh -e "SELECT * FROM test.text_set_set;"                                                                                 

